CREATE TABLE profiles (user TEXT PRIMARY KEY, email TEXT, verified INTEGER NOT NULL, name TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE issues (repo TEXT NOT NULL REFERENCES repos(id), number INTEGER NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, author TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('open','closed')), assignee TEXT, labels TEXT NOT NULL, version INTEGER NOT NULL, actor TEXT NOT NULL, created INTEGER NOT NULL, updated INTEGER NOT NULL, finding TEXT, PRIMARY KEY(repo,number), UNIQUE(repo,finding));
CREATE INDEX issues_search ON issues(repo,state,updated);
CREATE TABLE issue_comments (id TEXT PRIMARY KEY, repo TEXT NOT NULL, number INTEGER NOT NULL, author TEXT NOT NULL, body TEXT NOT NULL, created INTEGER NOT NULL, FOREIGN KEY(repo,number) REFERENCES issues(repo,number));
CREATE TABLE issue_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, repo TEXT NOT NULL, number INTEGER NOT NULL, actor TEXT NOT NULL, event TEXT NOT NULL, version INTEGER NOT NULL, data TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TRIGGER issue_created AFTER INSERT ON issues BEGIN INSERT INTO issue_audit(repo,number,actor,event,version,data,created) VALUES (NEW.repo,NEW.number,NEW.actor,'created',NEW.version,json_object('title',NEW.title,'state',NEW.state,'assignee',NEW.assignee,'labels',json(NEW.labels)),NEW.updated); END;
CREATE TRIGGER issue_updated AFTER UPDATE ON issues BEGIN INSERT INTO issue_audit(repo,number,actor,event,version,data,created) VALUES (NEW.repo,NEW.number,NEW.actor,'updated',NEW.version,json_object('title',NEW.title,'state',NEW.state,'assignee',NEW.assignee,'labels',json(NEW.labels)),NEW.updated); END;
CREATE TRIGGER issue_commented AFTER INSERT ON issue_comments BEGIN UPDATE issues SET version=version+1,actor=NEW.author,updated=NEW.created WHERE repo=NEW.repo AND number=NEW.number; INSERT INTO issue_audit(repo,number,actor,event,version,data,created) SELECT NEW.repo,NEW.number,NEW.author,'commented',version,json_object('comment',NEW.id),NEW.created FROM issues WHERE repo=NEW.repo AND number=NEW.number; END;
CREATE TABLE review_comments (id TEXT PRIMARY KEY, repo TEXT NOT NULL REFERENCES repos(id), proposal TEXT NOT NULL REFERENCES proposals(id), author TEXT NOT NULL, body TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE review_policy (repo TEXT PRIMARY KEY REFERENCES repos(id), publish INTEGER NOT NULL DEFAULT 0, actor TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE agent_audit (id TEXT PRIMARY KEY, repo TEXT NOT NULL REFERENCES repos(id), actor TEXT NOT NULL, event TEXT NOT NULL, data TEXT NOT NULL, created INTEGER NOT NULL);
